  functions: {
    'notify_generic_sources_change()':
      "CREATE OR REPLACE FUNCTION public.notify_generic_sources_change()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n    BEGIN\n      IF TG_OP = 'DELETE' THEN\n        PERFORM pg_notify('generic_sources_change', OLD.routing_key);\n      ELSE\n        PERFORM pg_notify('generic_sources_change', NEW.routing_key);\n      END IF;\n      RETURN NULL;\n    END;\n    $function$\n",
    'notify_sources_change()':
      "CREATE OR REPLACE FUNCTION public.notify_sources_change()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n    BEGIN\n      IF TG_OP = 'DELETE' THEN\n        PERFORM pg_notify('sources_change', OLD.routing_key);\n      ELSE\n        PERFORM pg_notify('sources_change', NEW.routing_key);\n      END IF;\n      RETURN NULL;\n    END;\n    $function$\n",
  },
